class Reset(AdminBaseClass):
    """
    Reset
    """

    def __init__(self):
        super(Reset, self).__init__()

    @check_rat
    def reset(self, **kwargs):
        """
        Reset
        """
        operation = kwargs.get("operation", "''")
        # alias = kwargs.get("alias", "default")
        kwargs = {key: value for key, value in list(kwargs.items()) if key not in ["operation"]}

        logger.debug("Performing operation  {}...".format(operation.upper().replace("_", " ")))
        try:
            getattr(self, "_{}".format(operation.lower()))(**kwargs)
        except AttributeError:
            raise Exception("Operation {} not supported".format(operation))

    def _reset_bts(self, **kwargs):
        self.reset_bts(**kwargs)

    def reset_bts(self, **kwargs):
        """ Resets BTS
            :param verify_bts: Boolean. to check if BTS status should be onAir or not
            :param req_rat: which RATs status to be checked.
            :param wait_for: Time to wait(seconds) before checking for status after reset
            :param alias: Name of execution context
        """
        verify_bts = kwargs.pop("verify_bts", True)
        req_rat = kwargs.pop("rat", 'all')
        should_be_onair = kwargs.pop("should_be_onair", True)
        wait_for = kwargs.pop("wait_for", 300)
        alias = kwargs.get("alias", 'default')
        logger.debug("performing site reset..")
        self.factory.admin.reset_site(timeout=300, connection=alias)
        logger.debug("performing ping test...")
        self._perform_ping_test(alias)
        if verify_bts:
            logger.debug("verifying bts status...")
            CellOperations().verify_bts_status(req_rat=req_rat, should_be_onair=should_be_onair,
                                               wait_for=wait_for, alias=alias)

    def _reset_admin(self, **kwargs):
        alias = kwargs.get("alias", 'default')
        self.factory.admin.reset_admin(connection=alias)

    def _reset_bts_rad_parameters(self, **kwargs):
        component = kwargs['component']
        params = kwargs['params']
        timeout = kwargs.pop('timeout', 300)
        alias = kwargs.pop("alias", 'default')

        self.factory.admin.reset_bts_rad_parameters(component=component, params=params, timeout=timeout,
                                                    connection=alias)

    def _reset_rad_debug_parameters(self, **kwargs):
        name = kwargs["name"]
        detailed_output = kwargs.get('detailed_output', False)
        timeout = kwargs.pop('timeout', 300)
        alias = kwargs.pop("alias", 'default')
        if name == "ALL":
            self.factory.admin.reset_all_rad_debug_parameters(timeout=timeout, detailed_output=detailed_output,
                                                              connection=alias)
        else:
            domain = kwargs['domain']
            self.factory.admin.reset_rad_debug_parameters(domain, name, timeout=timeout, detailed_output=detailed_output,
                                                          connection=alias)

