    def _reset_rat(self, **kwargs):
        rat = kwargs['rat']
        should_be_onair = kwargs.pop("should_be_onair", True)
        wait_for = kwargs.pop("wait_for", 300)
        timeout = kwargs.get('timeout', 300)
        alias = kwargs.get("alias", 'default')
        # self.factory.admin.reset_rat(rat=rat, timeout=timeout, connection=alias)
        self.factory.admin.reset_rat(rat_type=rat.upper(), timeout=timeout, connection=alias)
        verify_bts = kwargs.pop("verify_bts", True)
        if verify_bts:
            logger.debug("verifying bts status...")
            CellOperations().verify_bts_status(req_rat=rat, should_be_onair=should_be_onair,
                                               wait_for=wait_for, alias=alias)

    def _reset_to_test_dedicated(self, **kwargs):
        timeout = kwargs.pop('timeout', 300)
        alias = kwargs.get("alias", 'default')
        self.factory.admin.reset_to_test_dedicated(timeout=timeout, connection=alias)

