    def _reset_unit(self, **kwargs):
        """
             :param Boolean verify_bts: to check if BTS status should be onAir or not
             :param str dist_name: RMOD|GNSSE|GNSSI|RETU|ALD|BBMOD|ASIRMOD distName
             :param str reset_type: Soft|Hard|Warm
             :param int timeout:  Timeout for the operation. Defaults set to 120s.
             :param str connection: AdminConnection object or if used, string name alias.
             :param bool detailed_output: return full request response when True, defaults set to False.
             :param bool force_radio_reset: optional parameter to force radio reset. 'forceRadioReset' is only for RMOD|ASIRMOD.

             :return: NA
             :rtype: NA

        """
        dist_name = kwargs['dist_name']
        reset_type = kwargs.pop('reset_type', 'Soft')
        verify_bts = kwargs.pop("verify_bts", True)
        req_rat = kwargs.pop("rat", 'all')
        should_be_onair = kwargs.pop("should_be_onair", True)
        wait_for = kwargs.pop("wait_for", 300)
        alias = kwargs.get("alias", 'default')
        timeout = kwargs.pop('timeout', 60)
        detailed_output = kwargs.pop('detailed_output', False)
        force_radio_reset = kwargs.pop('force_radio_reset', None)
        # self.factory.admin.unit_reset_cp(dist_name=dist_name, timeout=timeout,
        #                                  reset_type=reset_type, connection=alias)
        self.factory.admin.reset_unit(dist_name=dist_name, timeout=timeout, reset_type=reset_type,
                                      force_radio_reset=force_radio_reset, detailed_output=detailed_output,
                                      connection=alias)
        if verify_bts:
            logger.debug("verifying bts status...")
            CellOperations().verify_bts_status(req_rat=req_rat, should_be_onair=should_be_onair,
                                               wait_for=wait_for, alias=alias)

    def verify_bts_reset_internal(self, **kwargs):
        """
        Function to verify bts reset.
        This will be used internally only. Keyword for any info-model operations will not be delivered for users as
        ute_admin_infomodel has stopped supporting the same.
        """
        # This function is deprecated

        alias = kwargs.pop("alias", 'default')
        timeout = kwargs.pop("timeout", 300)
        logger.debug('Verifying if BTS went for reset')
        self.factory.admin_infomodel.wait_for_infomodel_response_after_reset(
            timeout_for_reset=timeout, timeout_for_response=500, alias=alias)
        time.sleep(float(timeout))
        logger.debug('Reset was successful')

    def _perform_ping_test(self, alias):
        ping_timeout = 10
        dut = global_vars.alias_dut_dict[alias]
        bts_lmp_ip = get_config_variable([dut, 'ip'])
        for ping_attempt in range(ping_timeout):
            try:
                subprocess.check_output('ping -c 1 {}'.format(bts_lmp_ip), shell=True)
            except subprocess.CalledProcessError:
                pass
            else:
                logger.info('ping successful after {} seconds'.format(ping_attempt))
                break
        else:
            raise PingTestFailedException('ping unsuccessful after {} seconds'.format(
                ping_timeout))
